function flatten(groups) {
  const entries = [];
  for (const pack of Object.values(groups)) {
    for (const item of pack.items) {
      const { id, x, y, width: frameWidth, height: frameHeight } = item;
      entries.push([id, Object.freeze({
        group: pack.group, src: pack.src, width: pack.width, height: pack.height,
        sha256: pack.sha256, mode: pack.mode, alphaExtrema: pack.alphaExtrema,
        frame: Object.freeze({ x, y, width: frameWidth, height: frameHeight })
      })]);
    }
  }
  return Object.freeze(Object.fromEntries(entries));
}

